      [T("Выручка", "Tushum"), T("Заказы «Доставлен» минус проведённые возвраты", "«Yetkazildi» buyurtmalar minus o'tkazilgan qaytarishlar"), T("Заказ — по дате заказа; возврат — по дате проведения", "Buyurtma — buyurtma sanasi; qaytarish — o'tkazilgan sana")],
      [T("Себестоимость", "Tannarx"), T("Цена закупки товара на момент оформления заказа × довезено − себестоимость возвращённого", "Buyurtma rasmiylashtirilgan paytdagi xarid narxi × yetkazilgan − qaytarilganning tannarxi"), T("Вместе с выручкой", "Tushum bilan birga")],
      [T("Закупка (расходы приходов)", "Xarid (kirim xarajatlari)"), T("«Топливо», «Дорога», «Прочее» из завершённых приходов", "Yakunlangan kirimlardagi «Yoqilg'i», «Yo'l», «Boshqa»"), T("По дате прихода", "Kirim sanasi bo'yicha")],
