      [T("Валовая прибыль", "Yalpi foyda"), T("Выручка − себестоимость", "Tushum − tannarx"), T("—", "—")],
      [T("«Заработали за период»", "«Davr uchun foyda»"), T("Валовая прибыль − закупка − зарплата", "Yalpi foyda − xarid − ish haqi"), T("—", "—")],
